1	package server
2	
3	import (
4		"encoding/json"
5		"math"
6		"net/http"
7		"net/url"
8		"sort"
9	)
10	
11	const queryPath = "/api/v1/query"
12	
13	// ---- expression AST --------------------------------------------------------
14	
15	// queryExpr is one parsed expression: either a bare selector (aggregate ==
16	// "") or one of sum/avg/min/max, optionally grouped by non-empty by labels.
17	type queryExpr struct {
18		aggregate string
19		by        []string
20		metric    string
21		selector  map[string]string
22	}
23	
24	var queryAggregates = map[string]bool{
25		"sum": true,
26		"avg": true,
27		"min": true,
28		"max": true,
29	}
30	
31	// ---- expression parser -----------------------------------------------------
32	
33	type exprParser struct {
34		s string
35		p int
36	}
37	
38	// parseQueryExpr parses the single expression accepted by GET /api/v1/query.
39	// Whitespace is ASCII only and may surround any punctuation or keyword. The
40	// grammar:
41	//
42	//	expr        := selector | aggregation
43	//	aggregation := ident ("by" "(" ident ("," ident)* ")")? "(" selector ")"
44	//	selector    := ident "{" (ident "=" jsonString ("," ident "=" jsonString)*)? "}"
45	//
46	// The aggregation identifier must be one of sum/avg/min/max. Duplicate
47	// matchers or grouping labels, nested aggregations, unknown functions and any
48	// trailing input are rejected.
49	func parseQueryExpr(in string) (*queryExpr, bool) {
50		p := &exprParser{s: in}
51		p.skipSpaces()
52	
53		word, ok := p.parseIdent()
54		if !ok {
55			return nil, false
56		}
57		p.skipSpaces()
58	
59		e := &queryExpr{}
60		// A function name introduces an aggregation only when it is followed by a
61		// call ("(" or a by clause); followed by "{" it is simply a metric named
62		// like the keyword (metric writes impose no such reservation).
63		if queryAggregates[word] && (p.next() == '(' || p.hasIdent("by")) {
64			e.aggregate = word
65			if p.hasIdent("by") {
66				p.p += 2
67				p.skipSpaces()
68				if !p.expect('(') {
69					return nil, false
70				}
71				seen := make(map[string]bool)
72				for {
73					p.skipSpaces()
74					label, ok := p.parseIdent()
75					if !ok {
76						return nil, false
77					}
78					if seen[label] {
79						return nil, false
80					}
81					seen[label] = true
82					e.by = append(e.by, label)
83					p.skipSpaces()
84					switch p.next() {
85					case ',':
86						p.p++
87						continue
88					case ')':
89						p.p++
90					default:
91						return nil, false
92					}
93					break
94				}
95				p.skipSpaces()
96			}
97			if !p.expect('(') {
98				return nil, false
99			}
100			p.skipSpaces()
101			if !p.parseSelectorInto(e) {
102				return nil, false
103			}
104			p.skipSpaces()
105			if !p.expect(')') {
106				return nil, false
107			}
108		} else {
109			// The first identifier is the metric name; the selector body follows.
110			e.metric = word
111			if !p.expect('{') {
112				return nil, false
113			}
114			if !p.parseMatcherListInto(e) {
115				return nil, false
116			}
117		}
118	
119		p.skipSpaces()
120		if p.p != len(p.s) {
121			return nil, false
122		}
123		return e, true
124	}
125	
126	// parseSelectorInto parses metric "{" matcher-list "}" starting at the metric
127	// name; used for selectors nested inside an aggregation call.
128	func (p *exprParser) parseSelectorInto(e *queryExpr) bool {
129		name, ok := p.parseIdent()
130		if !ok {
131			return false
132		}
133		e.metric = name
134		p.skipSpaces()
135		if !p.expect('{') {
136			return false
137		}
138		return p.parseMatcherListInto(e)
139	}
140	
141	// parseMatcherListInto parses matcher-list "}" with the opening "{" consumed.
142	func (p *exprParser) parseMatcherListInto(e *queryExpr) bool {
143		e.selector = make(map[string]string)
144		p.skipSpaces()
145		if p.next() == '}' {
146			p.p++
147			return true
148		}
149		for {
150			p.skipSpaces()
151			key, ok := p.parseIdent()
152			if !ok {
153				return false
154			}
155			if _, dup := e.selector[key]; dup {
156				return false
157			}
158			p.skipSpaces()
159			if !p.expect('=') {
160				return false
161			}
162			p.skipSpaces()
163			value, ok := p.parseJSONString()
164			if !ok {
165				return false
166			}
167			e.selector[key] = value
168			p.skipSpaces()
169			switch p.next() {
170			case ',':
171				p.p++
172				continue
173			case '}':
174				p.p++
175				return true
176			default:
177				return false
178			}
179		}
180	}
181	
182	func (p *exprParser) next() byte {
183		if p.p >= len(p.s) {
184			return 0
185		}
186		return p.s[p.p]
187	}
188	
189	func (p *exprParser) expect(c byte) bool {
190		if p.next() != c {
191			return false
192		}
193		p.p++
194		return true
195	}
196	
197	func (p *exprParser) skipSpaces() {
198		for p.p < len(p.s) && isASCIISpace(p.s[p.p]) {
199			p.p++
200		}
201	}
202	
203	func isASCIISpace(c byte) bool {
204		return c == ' ' || ('\t' <= c && c <= '\r')
205	}
206	
207	func isIdentStart(c byte) bool {
208		return c == '_' || ('a' <= c && c <= 'z') || ('A' <= c && c <= 'Z')
209	}
210	
211	func isIdentCont(c byte) bool {
212		return isIdentStart(c) || '0' <= c && c <= '9'
213	}
214	
215	// parseIdent consumes an identifier matching identPattern and reports whether
216	// one was present.
217	func (p *exprParser) parseIdent() (string, bool) {
218		start := p.p
219		if p.p >= len(p.s) || !isIdentStart(p.s[p.p]) {
220			return "", false
221		}
222		for p.p < len(p.s) && isIdentCont(p.s[p.p]) {
223			p.p++
224		}
225		return p.s[start:p.p], true
226	}
227	
228	// hasIdent reports whether the text at the current position is exactly the
229	// given identifier (not part of a longer one), without consuming it.
230	func (p *exprParser) hasIdent(want string) bool {
231		end := p.p + len(want)
232		if end > len(p.s) || p.s[p.p:end] != want {
233			return false
234		}
235		return end == len(p.s) || !isIdentCont(p.s[end])
236	}
237	
238	// parseJSONString consumes a double-quoted JSON string literal and returns its
239	// decoded value. Escaping and Unicode handling follow JSON exactly.
240	func (p *exprParser) parseJSONString() (string, bool) {
241		if p.next() != '"' {
242			return "", false
243		}
244		start := p.p
245		p.p++
246		for p.p < len(p.s) {
247			switch c := p.s[p.p]; {
248			case c == '\\':
249				p.p += 2
250			case c == '"':
251				lit := p.s[start : p.p+1]
252				p.p++
253				var value string
254				if err := json.Unmarshal([]byte(lit), &value); err != nil {
255					return "", false
256				}
257				return value, true
258			default:
259				p.p++
260			}
261		}
262		return "", false
263	}
264	
265	// ---- execution -------------------------------------------------------------
266	
267	type querySample struct {
268		Labels map[string]string `json:"labels"`
269		Value  float64           `json:"value"`
270	}
271	
272	type queryResponse struct {
273		ResultType string        `json:"result_type"`
274		Result     []querySample `json:"result"`
275	}
276	
277	type matchedSeries struct {
278		labels map[string]string
279		value  float64
280	}
281	
282	// executeQuery evaluates a parsed expression against a single consistent
283	// store snapshot. Only current values of matching counter and gauge series
284	// participate; histograms are ignored. The third result is false when a
285	// selected value or an aggregate is not a finite number.
286	func (s *metricStore) executeQuery(e *queryExpr) ([]querySample, bool) {
287		s.mu.RLock()
288		defer s.mu.RUnlock()
289	
290		matched := make([]matchedSeries, 0)
291		for _, cur := range s.series {
292			if cur.typ != "counter" && cur.typ != "gauge" {
293				continue
294			}
295			if cur.name != e.metric {
296				continue
297			}
298			ok := true
299			for k, v := range e.selector {
300				got, exists := cur.labels[k]
301				if !exists || got != v {
302					ok = false
303					break
304				}
305			}
306			if !ok {
307				continue
308			}
309			if math.IsNaN(cur.value) || math.IsInf(cur.value, 0) {
310				return nil, false
311			}
312			matched = append(matched, matchedSeries{labels: copyLabels(cur.labels), value: cur.value})
313		}
314	
315		if e.aggregate == "" {
316			out := make([]querySample, 0, len(matched))
317			for _, m := range matched {
318				out = append(out, querySample{Labels: m.labels, Value: m.value})
319			}
320			sort.Slice(out, func(i, j int) bool {
321				return compareLabels(out[i].Labels, out[j].Labels) < 0
322			})
323			return out, true
324		}
325	
326		type groupAcc struct {
327			labels map[string]string
328			value  float64
329			count  int
330		}
331		groups := make(map[string]*groupAcc)
332		order := make([]string, 0)
333		for _, m := range matched {
334			projected := make(map[string]string, len(e.by))
335			for _, label := range e.by {
336				if v, ok := m.labels[label]; ok {
337					projected[label] = v
338				}
339			}
340			key := seriesKey("", projected)
341			g, seen := groups[key]
342			if !seen {
343				g = &groupAcc{labels: projected, value: m.value, count: 1}
344				groups[key] = g
345				order = append(order, key)
346				continue
347			}
348			g.count++
349			switch e.aggregate {
350			case "sum", "avg":
351				g.value += m.value
352			case "min":
353				if m.value < g.value {
354					g.value = m.value
355				}
356			case "max":
357				if m.value > g.value {
358					g.value = m.value
359				}
360			}
361		}
362	
363		out := make([]querySample, 0, len(order))
364		for _, key := range order {
365			g := groups[key]
366			value := g.value
367			if e.aggregate == "avg" {
368				value /= float64(g.count)
369			}
370			if math.IsNaN(value) || math.IsInf(value, 0) {
371				return nil, false
372			}
373			out = append(out, querySample{Labels: g.labels, Value: value})
374		}
375		sort.Slice(out, func(i, j int) bool {
