1	package server
2	
3	import (
4		"encoding/json"
5		"io"
6		"math"
7		"mime"
8		"net/http"
9		"sort"
10		"strings"
11		"time"
12	)
13	
14	const (
15		alertRulesPath   = "/api/v1/alert-rules"
16		alertRulesPrefix = alertRulesPath + "/"
17		alertsPath       = "/api/v1/alerts"
18	)
19	
20	// ruleSelector selects series by exact metric name and a subset of labels.
21	type ruleSelector struct {
22		metric string
23		labels map[string]string
24	}
25	
26	// alertRule is an immutable rule document. Replacements swap the pointer
27	// atomically, so readers never observe a half-updated rule.
28	type alertRule struct {
29		id        string
30		kind      string // "threshold" | "ratio"
31		operator  string // gt | gte | lt | lte
32		threshold float64
33	
34		// threshold rules use left only; ratio rules use both sides.
35		left  *ruleSelector
36		right *ruleSelector
37	}
38	
39	// ---- JSON wire shapes ------------------------------------------------------
40	
41	type ruleSideJSON struct {
42		Metric string            `json:"metric"`
43		Labels map[string]string `json:"labels"`
44	}
45	
46	type thresholdRuleJSON struct {
47		ID        string            `json:"id"`
48		Kind      string            `json:"kind"`
49		Operator  string            `json:"operator"`
50		Threshold float64           `json:"threshold"`
51		Metric    string            `json:"metric"`
52		Labels    map[string]string `json:"labels"`
53	}
54	
55	type ratioRuleJSON struct {
56		ID          string       `json:"id"`
57		Kind        string       `json:"kind"`
58		Operator    string       `json:"operator"`
59		Threshold   float64      `json:"threshold"`
60		Numerator   ruleSideJSON `json:"numerator"`
61		Denominator ruleSideJSON `json:"denominator"`
62	}
63	
64	func ruleWireJSON(r *alertRule) any {
65		if r.kind == "ratio" {
66			return ratioRuleJSON{
67				ID:          r.id,
68				Kind:        r.kind,
69				Operator:    r.operator,
70				Threshold:   r.threshold,
71				Numerator:   sideWireJSON(r.left),
72				Denominator: sideWireJSON(r.right),
73			}
74		}
75		return thresholdRuleJSON{
76			ID:        r.id,
77			Kind:      r.kind,
78			Operator:  r.operator,
79			Threshold: r.threshold,
80			Metric:    r.left.metric,
81			Labels:    copyLabels(r.left.labels),
82		}
83	}
84	
85	func sideWireJSON(s *ruleSelector) ruleSideJSON {
86		return ruleSideJSON{Metric: s.metric, Labels: copyLabels(s.labels)}
87	}
88	
89	// ---- request decoding ------------------------------------------------------
90	
91	type rawRuleSide struct {
92		Metric *string            `json:"metric"`
93		Labels *map[string]string `json:"labels"`
94	}
95	
96	type rawRule struct {
97		Kind        *string            `json:"kind"`
98		Operator    *string            `json:"operator"`
99		Threshold   *float64           `json:"threshold"`
100		Metric      *string            `json:"metric"`
101		Labels      *map[string]string `json:"labels"`
102		Numerator   *rawRuleSide       `json:"numerator"`
103		Denominator *rawRuleSide       `json:"denominator"`
104	}
105	
106	// decodeRule parses and fully validates a rule body. It never returns a
107	// partially validated rule.
108	func decodeRule(body []byte) (*alertRule, bool) {
109		var raw rawRule
110		if !strictDecode(body, &raw) {
111			return nil, false
112		}
113		if raw.Kind == nil || raw.Operator == nil || raw.Threshold == nil {
114			return nil, false
115		}
116		kind := *raw.Kind
117		if kind != "threshold" && kind != "ratio" {
118			return nil, false
119		}
120		operator := *raw.Operator
121		if !validOperators[operator] {
122			return nil, false
123		}
124		threshold := *raw.Threshold
125		if math.IsNaN(threshold) || math.IsInf(threshold, 0) {
126			return nil, false
127		}
128	
129		build := func() *alertRule {
130			return &alertRule{kind: kind, operator: operator, threshold: threshold}
131		}
132	
133		switch kind {
134		case "threshold":
135			if raw.Metric == nil || raw.Labels == nil || raw.Numerator != nil || raw.Denominator != nil {
136				return nil, false
137			}
138			sel, ok := decodeSelector(*raw.Metric, *raw.Labels)
139			if !ok {
140				return nil, false
141			}
142			r := build()
143			r.left = sel
144			return r, true
145		case "ratio":
146			if raw.Metric != nil || raw.Labels != nil || raw.Numerator == nil || raw.Denominator == nil {
147				return nil, false
148			}
149			num, ok := decodeRawSide(raw.Numerator)
150			if !ok {
151				return nil, false
152			}
153			den, ok := decodeRawSide(raw.Denominator)
154			if !ok {
155				return nil, false
156			}
157			r := build()
158			r.left, r.right = num, den
159			return r, true
160		}
161		return nil, false
162	}
163	
164	func decodeRawSide(raw *rawRuleSide) (*ruleSelector, bool) {
165		if raw.Metric == nil || raw.Labels == nil {
166			return nil, false
167		}
168		return decodeSelector(*raw.Metric, *raw.Labels)
169	}
170	
171	func decodeSelector(metric string, labels map[string]string) (*ruleSelector, bool) {
172		if !identPattern.MatchString(metric) || labels == nil {
173			return nil, false
174		}
175		for k := range labels {
176			if !identPattern.MatchString(k) {
177				return nil, false
178			}
179		}
180		return &ruleSelector{metric: metric, labels: copyLabels(labels)}, true
181	}
182	
183	var validOperators = map[string]bool{
184		"gt":  true,
185		"gte": true,
186		"lt":  true,
187		"lte": true,
188	}
189	
190	// ---- store operations ------------------------------------------------------
191	
192	func (s *metricStore) putRule(r *alertRule) bool {
193		s.mu.Lock()
194		defer s.mu.Unlock()
195		_, existed := s.rules[r.id]
196		s.rules[r.id] = r
197		return !existed
198	}
199	
200	func (s *metricStore) getRule(id string) (*alertRule, bool) {
201		s.mu.RLock()
202		defer s.mu.RUnlock()
203		r, ok := s.rules[id]
204		return r, ok
205	}
206	
207	func (s *metricStore) deleteRule(id string) bool {
208		s.mu.Lock()
209		defer s.mu.Unlock()
210		if _, ok := s.rules[id]; !ok {
211			return false
212		}
213		delete(s.rules, id)
214		return true
215	}
216	
217	// snapshotRules returns all rules sorted by id. Rule objects are immutable,
218	// so the pointers stay safe after the lock is released.
219	func (s *metricStore) snapshotRules() []*alertRule {
220		s.mu.RLock()
221		defer s.mu.RUnlock()
222		out := make([]*alertRule, 0, len(s.rules))
223		for _, r := range s.rules {
224			out = append(out, r)
225		}
226		sort.Slice(out, func(i, j int) bool { return out[i].id < out[j].id })
227		return out
228	}
229	
230	// selectorSum sums current values of all matching counter/gauge series.
231	// ok is false when no counter/gauge series matches; histograms are ignored,
232	// so a selector matching histograms only counts as unavailable.
233	func (s *metricStore) selectorSum(sel *ruleSelector) (sum float64, ok bool) {
234		for _, cur := range s.series {
235			if cur.typ != "counter" && cur.typ != "gauge" {
236				continue
237			}
238			if cur.name != sel.metric {
239				continue
240			}
241			matched := true
242			for k, v := range sel.labels {
243				got, exists := cur.labels[k]
244				if !exists || got != v {
245					matched = false
246					break
247				}
248			}
249			if !matched {
250				continue
251			}
252			sum += cur.value
253			ok = true
254		}
255		return sum, ok
256	}
257	
258	type alertOutput struct {
259		ID            string   `json:"id"`
260		State         string   `json:"state"`
261		Value         *float64 `json:"value"`
262		Silenced      bool     `json:"silenced"`
263		SilenceIDs    []string `json:"silence_ids"`
264		Inhibited     bool     `json:"inhibited"`
265		InhibitionIDs []string `json:"inhibition_ids"`
266	}
267	
268	// evalAlerts computes every rule against a single consistent snapshot of
269	// metrics, rules, silences and inhibit rules; results are sorted by rule id.
270	// Original state, value and silencing are evaluated first; inhibition is then
271	// applied to the original firing states so silenced or inhibited alerts still
272	// act as inhibition sources.
273	func (s *metricStore) evalAlerts() []alertOutput {
274		s.mu.RLock()
275		defer s.mu.RUnlock()
276		return s.evalAlertsLocked()
277	}
278	
279	// evalAlertsLocked computes every rule against a single consistent snapshot
280	// already held by the caller. Callers that also need other state (e.g. the
281	// notification plan's routes) share one snapshot by holding s.mu themselves.
282	func (s *metricStore) evalAlertsLocked() []alertOutput {
283		rules := make([]*alertRule, 0, len(s.rules))
284		for _, r := range s.rules {
285			rules = append(rules, r)
286		}
287		sort.Slice(rules, func(i, j int) bool { return rules[i].id < rules[j].id })
288	
289		silences := make([]*silence, 0, len(s.silences))
290		for _, sil := range s.silences {
291			silences = append(silences, sil)
292		}
293		inhibitRules := make([]*inhibitRule, 0, len(s.inhibitions))
294		for _, ir := range s.inhibitions {
295			inhibitRules = append(inhibitRules, ir)
296		}
297		// Evaluation instant and silence windowing share the snapshot.
298		now := time.Now()
299		activeByRule := activeSilencesByRule(silences, now)
300	
301		out := make([]alertOutput, 0, len(rules))
302		for _, r := range rules {
303			al := alertOutput{ID: r.id, State: "inactive", SilenceIDs: []string{}, InhibitionIDs: []string{}}
304	
305			var value float64
306			if r.kind == "threshold" {
307				sum, ok := s.selectorSum(r.left)
308				if !ok {
309					al.State = "no_data"
310					out = append(out, al)
311					continue
312				}
313				value = sum
314			} else {
315				num, numOK := s.selectorSum(r.left)
316				den, denOK := s.selectorSum(r.right)
317				if !numOK || !denOK || den == 0 {
318					al.State = "no_data"
319					out = append(out, al)
320					continue
