func sortLogs(out []*logEntry) {
	sort.Slice(out, func(i, j int) bool {
		ni, nj := out[i].ts.UnixNano(), out[j].ts.UnixNano()
		if ni != nj {
			return ni > nj
		}
		return out[i].id < out[j].id
	})
}

